package com.bank.jvm.zgc;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class FraudScoringSimulator {
    private static final Logger log = Logger.getLogger(FraudScoringSimulator.class.getName());

    public static void main(String[] args) {
        GcObserver observer = new GcObserver();
        log.info("Bank: National Bank of India — ZGC fraud-scoring simulator");
        observer.snapshot("before");

        // Long-lived graph: settles into the OLD generation and is rarely moved.
        TransactionGraph graph = new TransactionGraph(200_000);
        log.info(() -> "Built long-lived graph of " + graph.size() + " nodes");

        // Short-lived scoring contexts: churn through the YOUNG generation.
        long highRisk = 0;
        for (int i = 0; i < 5_000_000; i++) {
            ScoringContext ctx = new ScoringContext("TXN-" + i, new BigDecimal("50000"), graph);
            if (ctx.score() > 7) highRisk++;
            if (i % 1_000_000 == 0) observer.snapshot("during");
        }

        log.info(() -> "High-risk transactions flagged: " + highRisk);
        observer.snapshot("after");
        log.info("ZGC kept pauses sub-ms; young GC reclaimed the scoring churn");
    }
}

// ─── Would be in TransactionGraph.java in a real project ───
class TransactionGraph {
    private final long[] nodeHashes; // large, long-lived structure

    TransactionGraph(int nodes) {
        this.nodeHashes = new long[nodes];
        for (int i = 0; i < nodes; i++) nodeHashes[i] = (long) i * 2654435761L;
    }
    int size() { return nodeHashes.length; }
    long neighbourHash(int seed) { return nodeHashes[Math.floorMod(seed, nodeHashes.length)]; }
}

// ─── Would be in ScoringContext.java in a real project ───
class ScoringContext {
    private final String txnId;
    private final BigDecimal amount;
    private final TransactionGraph graph;
    private final int[] features = new int[32]; // short-lived payload

    ScoringContext(String txnId, BigDecimal amount, TransactionGraph graph) {
        this.txnId = txnId;
        this.amount = amount;
        this.graph = graph;
    }
    int score() {
        long h = graph.neighbourHash(txnId.hashCode());
        int s = (int) (h & 0xF) + (amount.intValue() % 3);
        for (int f : features) s ^= f;
        return s & 0xF;
    }
}
