package com.bank.jvm.zgc;

import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.util.logging.Logger;

class GcObserver {
    private static final Logger log = Logger.getLogger(GcObserver.class.getName());

    void snapshot(String phase) {
        long totalCount = 0, totalMs = 0;
        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            totalCount += Math.max(gc.getCollectionCount(), 0);
            totalMs += Math.max(gc.getCollectionTime(), 0);
        }
        final long c = totalCount, t = totalMs;
        log.info(() -> "GC [" + phase + "] collections=" + c + " totalPauseMs=" + t);
    }
}
